export { GameRoom } from "./worker/src/room.js";
/** Hogwarts: Last Midnight. Release 0.1: room + persistent character creation. */
const ROOM_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const ALLOWED_HOUSES = ['gryffindor','slytherin','ravenclaw','hufflepuff'];
const ALLOWED_TRAITS = ['insight','courage','empathy','logic'];
const ALLOWED_HAIR = ['crop','part','waves','long','bun','shaved'];
const ALLOWED_ROBES = ['classic','traveler','ceremony'];
const ALLOWED_WANDS = ['oak','ash','willow','yew'];
const NUMERIC = ['headWidth','jaw','cheek','chin','eyes','eyeSpacing','nose','noseWidth','mouth','brow','age','bodyHeight'];
const COLOR = ['skin','eyesColor','hairColor'];

function reply(body, status = 200, headers = {}) {
  return new Response(JSON.stringify(body), {
    status, headers: {
      'content-type':'application/json; charset=utf-8',
      'cache-control':'no-store',
      'x-content-type-options':'nosniff',
      ...headers,
    },
  });
}
function bad(message, status=400){ return reply({ok:false,error:message}, status); }
function newToken(bytes=24){
  const a=crypto.getRandomValues(new Uint8Array(bytes));
  return Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');
}
function newCode(){
  const a=crypto.getRandomValues(new Uint8Array(6));
  return Array.from(a,x=>ROOM_CHARS[x % ROOM_CHARS.length]).join('');
}
async function digest(s) {
  const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));
  return Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
}
async function bodyJson(req){
  const text=await req.text();
  if(text.length>12000)throw new Error('Слишком большой запрос');
  try{return text?JSON.parse(text):{};}catch{throw new Error('Некорректные данные');}
}
function normalizeCode(s){ return String(s||'').trim().toUpperCase(); }
function safeName(s){
  const n=String(s||'').trim().replace(/\s+/g,' ');
  if(!n || n.length>32 || /[<>\x00-\x1f]/.test(n)) throw new Error('Имя должно содержать от 1 до 32 символов без специальных знаков');
  return n;
}
function safeColor(s){ return typeof s==='string' && /^#[0-9a-fA-F]{6}$/.test(s); }
function safeCharacter(raw) {
  if(!raw || typeof raw!=='object' || Array.isArray(raw)) throw new Error('Персонаж не задан');
  const obj={};
  obj.name=safeName(raw.name);
  if (raw.base !== undefined) {
    if (!['wizard', 'witch'].includes(raw.base)) throw new Error('Некорректный тип персонажа');
    obj.base = raw.base;
  }
  for(const field of NUMERIC){
    const v=Number(raw[field]);
    if(!Number.isFinite(v)||v<0||v>100) throw new Error('Некорректный параметр: '+field);
    obj[field]=Math.round(v);
  }
  for(const field of COLOR){
    if(!safeColor(raw[field])) throw new Error('Некорректный цвет: '+field);
    obj[field]=raw[field].toLowerCase();
  }
  for(const [field,allowed] of [['hair',ALLOWED_HAIR],['robe',ALLOWED_ROBES],['wand',ALLOWED_WANDS],['house',ALLOWED_HOUSES],['trait',ALLOWED_TRAITS]]){
    if(!allowed.includes(raw[field]))throw new Error('Некорректный параметр: '+field);
    obj[field]=raw[field];
  }
  obj.beard = Number.isInteger(raw.beard) && raw.beard>=0 && raw.beard<=3 ? raw.beard : 0;
  return obj;
}
async function getState(db,code) {
  const r=await db.prepare('SELECT code,status,max_players,revision,created_at FROM rooms WHERE code=?').bind(code).first();
  if(!r)return null;
  const {results}=await db.prepare('SELECT id,display_name,character_json,ready,created_at FROM players WHERE room_code=? ORDER BY created_at,id').bind(code).all();
  return {
    code:r.code, status:r.status, maxPlayers:r.max_players, revision:r.revision,createdAt:r.created_at,
    players:results.map(p=>({id:p.id,name:p.display_name,character:p.character_json?JSON.parse(p.character_json):null,ready:!!p.ready})),
  };
}
async function checkHost(req,room){
  const token=req.headers.get('x-host-token')||'';
  return token.length>0 && (await digest(token))===room.host_token_hash;
}
async function checkPlayer(req,db,code,id){
  const p=await db.prepare('SELECT * FROM players WHERE id=? AND room_code=?').bind(id,code).first();
  if(!p)return null;
  const token=req.headers.get('x-player-token')||'';
  if(!token || (await digest(token))!==p.token_hash)return null;
  return p;
}
async function api(req,url,env) {
  if(!env.DB)return bad('База данных не подключена',503);
  const path=url.pathname;
  if(path==='/api/health' && req.method==='GET')return reply({ok:true,stage:'character-editor',version:'0.1.0'});
  if(path==='/api/rooms' && req.method==='POST'){
    const hostToken=newToken(); const hash=await digest(hostToken);
    let code; let created=false;
    for(let i=0;i<7;i++){
      code=newCode();
      const res=await env.DB.prepare('INSERT INTO rooms(code,host_token_hash) VALUES (?,?) ON CONFLICT DO NOTHING').bind(code,hash).run();
      if(res.meta.changes){created=true;break;}
    }
    if(!created)return bad('Не удалось создать комнату',503);
    return reply({ok:true,code,hostToken,state:await getState(env.DB,code)},201);
  }
  const roomMatch=path.match(/^\/api\/rooms\/([A-Z0-9]{6})$/);
  if(roomMatch && req.method==='GET'){
    const state=await getState(env.DB,roomMatch[1]);
    return state?reply({ok:true,state}):bad('Комната не найдена',404);
  }
  const joinMatch=path.match(/^\/api\/rooms\/([A-Z0-9]{6})\/join$/);
  if(joinMatch && req.method==='POST'){
    const code=joinMatch[1];
    const room=await env.DB.prepare('SELECT * FROM rooms WHERE code=?').bind(code).first();
    if(!room)return bad('Комната не найдена',404);
    if(room.status!=='lobby')return bad('Приём игроков уже завершён',409);
    const input=await bodyJson(req);const name=safeName(input.name);
    const id=newToken(12),token=newToken(),tokenHash=await digest(token);
    // Atomic capacity check: concurrent joins cannot exceed the room limit.
    try {
      const result=await env.DB.prepare(`INSERT INTO players(id,room_code,display_name,token_hash)
        SELECT ?,?,?,? WHERE (SELECT COUNT(*) FROM players WHERE room_code=?) < (SELECT max_players FROM rooms WHERE code=? AND status='lobby')`)
        .bind(id,code,name,tokenHash,code,code).run();
      if(!result.meta.changes)return bad('В комнате уже нет свободных мест',409);
    }catch(e){
      if(/UNIQUE/i.test(String(e)))return bad('Такое имя уже занято в комнате',409);
      throw e;
    }
    await env.DB.prepare('UPDATE rooms SET revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE code=?').bind(code).run();
    return reply({ok:true,playerId:id,playerToken:token,state:await getState(env.DB,code)},201);
  }
  const edit=path.match(/^\/api\/rooms\/([A-Z0-9]{6})\/players\/([a-f0-9]{24})$/);
  if(edit && req.method==='PATCH'){
    const [,code,id]=edit;
    const p=await checkPlayer(req,env.DB,code,id);
    if(!p)return bad('Нет доступа к персонажу',403);
    const room=await env.DB.prepare('SELECT status FROM rooms WHERE code=?').bind(code).first();
    if(!room || room.status!=='lobby')return bad('Редактирование завершено',409);
    const input=await bodyJson(req);
    const character = input.character === undefined ? (p.character_json?JSON.parse(p.character_json):null) : safeCharacter(input.character);
    const ready = input.ready===undefined ? !!p.ready : input.ready===true;
    if(ready && !character)return bad('Сначала создайте персонажа');
    await env.DB.prepare(`UPDATE players SET character_json=?,ready=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND room_code=?`)
      .bind(character?JSON.stringify(character):null,ready?1:0,id,code).run();
    await env.DB.prepare('UPDATE rooms SET revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE code=?').bind(code).run();
    return reply({ok:true,state:await getState(env.DB,code)});
  }
  const start=path.match(/^\/api\/rooms\/([A-Z0-9]{6})\/start$/);
  if(start && req.method==='POST'){
    const code=start[1],room=await env.DB.prepare('SELECT * FROM rooms WHERE code=?').bind(code).first();
    if(!room)return bad('Комната не найдена',404);
    if(!(await checkHost(req,room)))return bad('Только ведущий может начать',403);
    const state=await getState(env.DB,code);
    if(state.players.length<3)return bad('Нужно минимум три игрока',409);
    if(state.players.some(x=>!x.ready||!x.character))return bad('Не все персонажи готовы',409);
    await env.DB.prepare("UPDATE rooms SET status='prologue',revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE code=? AND status='lobby'").bind(code).run();
    return reply({ok:true,state:await getState(env.DB,code)});
  }
  return bad('Маршрут не найден',404);
}
const assets = {"/prologue.html": ["text/html", ""], "/play.html": ["text/html", ""], "/tv.html": ["text/html", ""], "/index.html": ["text/html", ""], "/assets/landing.js": ["text/javascript", ""], "/assets/tv.js": ["text/javascript", ""], "/assets/avatar3d.js": ["text/javascript", ""], "/assets/hogwarts-logo.webp": ["image/webp", ""], "/assets/player.js": ["text/javascript", ""], "/assets/common.js": ["text/javascript", ""], "/assets/prologue.js": ["text/javascript", ""], "/assets/theme.css": ["text/css", ""], "/assets/wizard-portrait.webp": ["image/webp", ""], "/assets/witch-portrait.webp": ["image/webp", ""]};
function serveAsset(path) {
  const asset = Object.hasOwn(assets, path) && assets[path];
  if (!asset) return new Response("Not found", {status: 404});
  return new Response(Uint8Array.from(atob(asset[1]), char => char.charCodeAt(0)), {headers: {"content-type": asset[0]}});
}
export default {
  async fetch(request,env){
    const url=new URL(request.url);
    const gamePath = '/hogwarts_ny';
    if (url.pathname === gamePath) {
      url.pathname += '/';
      return Response.redirect(url, 307);
    }
    if (url.pathname.startsWith(gamePath + '/')) {
      url.pathname = url.pathname.slice(gamePath.length);
    }
    if(url.pathname.startsWith('/api/')){
      if(!['GET','POST','PATCH'].includes(request.method))return bad('Метод не поддерживается',405);
      try{return await api(request,url,env);}
      catch(e){
        if(e instanceof SyntaxError || (e instanceof Error && (/Некорректн|Слишком большой|не задан|Имя должно/.test(e.message))))return bad(e.message);
        console.error('API error',e);
        return bad('Ошибка сервера',500);
      }
    }
    return serveAsset(url.pathname === '/' ? '/index.html' : url.pathname);
  }
};
